    "epsilon_cutoff": ["keyword", "float", "Ry", true, "", "Energy cutoff for the dielectric matrix, in Ry. The dielectric matrix\n$\\varepsilon_{GG'}$ will contain all G-vectors with kinetic energy $|q+G|^2$\nup to this cutoff.", [], [], "35.0"],
    "eqp_corrections": ["keyword", "toggle", "", false, "", "Set this to use eigenvalues in eqp.dat and eqp_q.dat\nIf not set, these files will be ignored.", [], [], ""],
    "ev0": ["keyword", "float", "", false, "", "", [], [], "0.0"],
    "evdel": ["keyword", "float", "", false, "", "", [], [], "0.0"],
    "evs": ["keyword", "float", "", false, "", "**Scissors operator**\nScissors operator (linear fit of the quasiparticle\nenergy corrections) for the bands in `WFN` and `WFNq`.\nFor valence-band energies:\n\n- `ev_cor = ev_in + evs + evdel * (ev_in - ev0)`\n\nFor conduction-band energies:\n\n- `ec_cor = ec_in + ecs + ecdel * (ec_in - ec0)`\n\nDefaults is zero for all entries, i.e., no scissors corrections.\n`evs`, `ev0`, `ecs`, `ec0` are in eV.\nIf you have `eqp.dat` and `eqp_q.dat` files\nthis information is ignored in favor of the eigenvalues\nin eqp.dat and eqp_q.dat.\nOne can specify all parameters for scissors operator\nin a single line with `cvfit evs ev0 evdel ecs ec0 ecdel`", [], [], "0.0"],
    "fermi_level": ["keyword", "float", "", false, "", "Specify the Fermi level (in eV), if you want implicit doping\nNote that value refers to energies *after* scissor shift or eqp corrections.\nSee also `fermi_level_absolute` and `fermi_level_relative` to control\nthe meaning of the Fermi level.", [], [], "0.0"],
    "fermi_level_absolute": ["keyword", "toggle", "", false, "", "The Fermi level in keyword `fermi_level` can be treated as an absolute\nvalue or relative to that found from the mean field (default). Using\n`fermi_level_absolute` will force the code to recompute the Fermi level\nregardless of existing occupations/ifmax array.", [], [], ""],
    "fermi_level_relative": ["keyword", "toggle", "", false, "", "", [], [], ""],
    "frequency_dependence": ["keyword", "integer", "", false, "", "This flags specifies the frequency dependence of the inverse dielectric matrix:\n\n- Set to 0 to compute the static inverse dielectric matrix (default).\n- Set to 2 to compute the full frequency dependent inverse dielectric matrix.\n- Set to 3 to compute the two frequencies needed for Godby-Needs GPP model.", [["0","compute the static inverse dielectric matrix (default)."],["2","compute the full frequency dependent inverse dielectric matrix."],["3","compute the two frequencies needed for Godby-Needs GPP model."]], [], "0"],
    "frequency_dependence_method": ["keyword", "integer", "", false, "", "**Parameters for full-frequency-dependent calculations**\nThree methods are available, depending on the value of `frequency_dependence_method`:\n\n- 0: Real-axis formalism with Adler-Wiser formula:\n\n    - A uniform frequency grid is set up from `init_frequency` (defaults to 0),\n      up to `frequency_low_cutoff`, with a spacing of `delta_frequency` between\n      two frequencies.\n    - A non-uniform frequency grid is setup from `frequency_low_cutoff` to\n      `frequency_high_cutoff`, where the frequency spacing gets increased by\n      `delta_frequency_step`.\n\n- 1: Real-axis formalism with spectral method:\n\n    - A uniform frequency grid is set up from `init_frequency` (defaults to 0),\n      up to `frequency_low_cutoff`, with a spacing of `delta_frequency` between\n      two frequencies.\n    - A non-uniform frequency grid is setup from `frequency_low_cutoff` to\n      `frequency_high_cutoff`, where the frequency spacing gets increased by\n      `delta_frequency_step`.\n    - A separate frequency grid is set-up for the spectral function. The variables\n      `init_sfrequency`, `delta_sfrequency`, `delta_sfrequency_step`,\n      `sfrequency_low_cutoff`, and `sfrequency_high_cutoff` define this grid, in\n      an analogy to the flags used to define the grid for the polarizability matrix.\n\n- 2: Contour-deformation formalism with Adler-Wiser formula (**default**).\n\n    - A uniform frequency grid is set up from `init_frequency` (defaults to 0),\n      up to `frequency_low_cutoff`, with a spacing of `delta_frequency` between\n      two frequencies.\n    - A frequency grid with `number_imaginary_freqs` is set-up on the imag axis.\n\n\nFull frequency dependence method for the polarizability, if `frequency_dependence`==2:\n\n- 0: Real-axis formalism, Adler-Wiser formula.\n- 1: Real-axis formalism, spectral method (PRB 74, 035101, (2006))\n- 2: Contour-deformation formalism, Adler-Wiser formula.", [["0","Real-axis formalism with Adler-Wiser formula:"],["1","Real-axis formalism with spectral method:"],["2","Contour-deformation formalism with Adler-Wiser formula (**default**)."],["0","Real-axis formalism, Adler-Wiser formula."],["1","Real-axis formalism, spectral method (PRB 74, 035101, (2006))"],["2","Contour-deformation formalism, Adler-Wiser formula."]], [], "2"],
    "frequency_high_cutoff": ["keyword", "float", "", false, "", "Upper limit of the non-uniform frequency grid.\nDefaults to 4*`frequency_low_cutoff`", [], [], "1000.0"],
    "frequency_low_cutoff": ["keyword", "float", "", false, "", "Upper bound for the linear frequency grid.\nFor methods 0 and 1, it is also the lower bound for the non-uniform frequency grid.\nShould be larger than the maximum transition, i.e., the\nenergy difference between the highest conduction band and the lowest valence band.\nThe default is 200 eV for method 0 and 1, and 10 eV for method 2.\nFor method 2, you can increase frequency_low_cutoff if you wish to use\nthe Sigma code and look into QP states deep in occupied manifold or high in\nthe unoccupied manifold.", [], [], "200.0"],
    "full_chi_conv_log": ["keyword", "integer", "", false, "", "Logging convergence of the head & tail of polarizability matrix with respect to conduction bands:\n\n- Set to -1 for no convergence test\n- Set to 0 for the 5 column format including the extrapolated values (default).\n- Set to 1 for the 2 column format, real part only.\n- Set to 2 for the 2 column format, real and imaginary parts.", [["-1","for no convergence test"],["0","for the 5 column format including the extrapolated values (default)."],["1","for the 2 column format, real part only."],["2","for the 2 column format, real and imaginary parts."]], [], "-1"],
    "fullbz_replace": ["keyword", "toggle", "", false, "", "'unfolded BZ' is from the kpoints in the WFN file\n'full BZ' is generated from the kgrid parameters in the WFN file\nSee comments in Common/checkbz.f90 for more details\n\n\nReplace unfolded BZ with full BZ", [], [], ""],
    "fullbz_write": ["keyword", "toggle", "", false, "", "Write unfolded BZ and full BZ to files", [], [], ""],
