    "max_mem_nv_block_algo": ["keyword", "float", "", false, "", "", [], [], "2.0"],
    "mtxel_algo": ["keyword", "toggle", "", false, "", "**GPUs Parameters**\nInput parameters controlling the execution when running with GPU support.\nFor the default algorithm (keys ending with `_algo`) the hierarchy depends on which programming models are compiled in (OpenACC, OpenMP-target and/or CPU (threaded or not)):\nif all possible implementations have been compiled then the hierarchy is `OPENACC_ALGO` > `OMP_TARGET_ALGO` > `CPU_ALGO`.\n\n\nControlling which algorithm to use for the GPU offload of the `mtxel` kernel calculating transition matrix elements.\nPossible values are `CPU_ALGO`, `OPENACC_ALGO` and `OMP_TARGET_ALGO` (See section header for default values).", [], [], ""],
    "n_ffts_per_batch": ["keyword", "integer", "", false, "", "Control how many FFTs to perform simultaneously in the batched `mtxel` kernel (Default 20).\nIf set to -1 the band by band `mtxel` kernel will be used, see `accel_mtxel_band_block_size`.", [], [], "10"],
    "nbasis_subspace": ["keyword", "integer", "", false, "", "Define a maximum fixed number of eigenvectors to be used (recommended). Set for example to 25% of the number of G-vectors\nemployed for the expansion of chi0.", [], [], "-1"],
    "nfreq_group": ["keyword", "integer", "", false, "", "(Full Frequency only) Calculates several frequencies in parallel. No \"new\"\nprocessors are used here, the chi summation is simply done in another order\nway to decrease communication. This also allows the inversion of multiple\ndielectric matrices simultaneously via ScaLAPACK, circumventing ScaLAPACK's\nscaling problems. Can be very efficient for system with lots of G-vectors and when\nyou have many frequencies. In general gives speedup. However, in order to\ncalculate N frequencies in parallel, the memory to store `pol%gme` is currently\nmultiplied by N as well.", [], [], "1"],
    "no_min_fftgrid": ["keyword", "toggle", "", false, "", "Instead of using the RHO FFT box to perform convolutions, we automatically\ndetermine (and use) the smallest box that is compatible with your epsilon\ncutoff. This also reduces the amount of memory needed for the FFTs.\nAlthough this optimization is safe, you can disable it by uncommenting the\nfollowing line:", [], [], ""],
    "number_bands": ["keyword", "integer", "", false, "", "Total number of bands (valence+conduction) to sum over. Defaults to the\nnumber of bands in the WFN file minus 1.", [], [], "1000"],
    "number_imaginary_freqs": ["keyword", "integer", "", false, "", "Number of frequencies on the imaginary axis for method 2.", [], [], "15"],
    "number_valence_pools": ["keyword", "integer", "", false, "", "Number of pools for distribution of valence bands\nThe default is chosen to minimize memory in calculation", [], [], "1"],
    "nv_block": ["keyword", "integer", "", false, "", "Input parameters to activate the valence bands blocked algorithm. Particularly useful in case of memory issues,\nthe entire epsilon computation is broken into blocks of valence bands, and block size can be given in input such\nthat memory limit is not exceeded in the allocation of the matrix elements array (`pol%gme`). You can either specify\nthe block size (`nv_block`) or the max memory (in Gb) available per MPI task (`max_mem_nv_block_algo`).", [], [], "3"],
    "occ_broadening": ["keyword", "float", "", false, "", "Apply the first order Methfessel-Paxton smearing scheme to the band occupations. Note that this keyword must be\nused with fermi_level_absolute.", [], [], "0.0"],
    "partial_occ_degeneracy_tolerance": ["keyword", "float", "", false, "", "Allows to define the threshold for determine the degeneracy between partially occupied valence and conduction eigenvalues\nin the computation of transition matrix elements (default 1.0E-6).", [], [], "0.00002"],
    "plasma_freq": ["keyword", "float", "", false, "", "Plasma frequency (eV) needed for the contour-deformation method (i.e.,\n`frequency_dependence`==2). The exact value\nis unimportant, especially if you have enough imaginary frequency points. We\nrecommend you keep this value fixed at 2 Ry.", [], [], "27.21138506d0"],
    "qgrid": ["keyword", "array", "", false, "", "Q-grid for the epsmat file. Defaults to the WFN k-grid.", [], [], "0 0 0"],
    "qpoints": ["block", "block", "", true, "", "qx qy qz 1/scale_factor is_q0\n\nscale_factor is for specifying values such as 1/3\nis_q0 = 0 for regular, non-zero q-vectors (read val WFNs from `WFN`)\nis_q0 = 1 for a small q-vector in semiconductors (read val WFNs from `WFNq`)\nis_q0 = 2 for a small q-vector in metals (read val WFNs from `WFN`)\nif present the small q-vector should be first in the list\nYou can generate this list with `kgrid.x`: just set the shifts to zero and use\nsame grid numbers as for `WFN`. Then replace the zero vector with q0.\nIn the case of RPA energy calculations (`do_rpa`) an additional value\nat the end of each q-point line has to be specified with the weight of the q-point for the BZ integration,\n`do_rpa` flag needs to be specified before the `begin qpoints` block.", [], ["qx","qy","qz","1/scale_factor","is_q0"], ""],
    "read_chi_add": ["keyword", "toggle", "", false, "", "Read in screening files (chimat and chi0mat) for system outside of the electronic system\nin your current calculation to add to the electronic polarizability you calculate.\nFor example, you could include the fluid polarizability from the JDFTx computational package,\nor the electronic polarizabilities for the substrate for your electronic system that you\ncalculated previously. Works only with hdf5 and you have to have the following files in your directory:\n`chi0mat_add.h5` and `chimat_add.h5` (only the latter if you are working on a metallic system).", [], [], ""],
    "read_chi_maxmem_per_block": ["keyword", "float", "", false, "", "When using `skip_chi` allows to control the max memory (in Mb) to use when reading in\nblock of columns of chimat in h5 format.", [], [], "256.0"],
    "restart": ["keyword", "toggle", "", false, "", "Use this flag if you would like to restart your Epsilon calculation\ninstead of starting it from scratch. Note that we can only reuse q-points\nthat were fully calculated. This flag is ignored unless you are running\nthe code with HDF5.", [], [], ""],
    "sfrequency_high_cutoff": ["keyword", "float", "", false, "", "Upper limit of the non-uniform frequency grid for the spectral function method.\nDefaults to `frequency_low_cutoff`", [], [], "200.0"],
