    "skip_chi": ["keyword", "toggle", "", false, "", "", [], [], ""],
    "skip_epsilon": ["keyword", "toggle", "", false, "", "By default, the code computes the polarizability matrix, constructs\nthe dielectric matrix, inverts it and writes the result to file epsmat.\nUse keyword skip_epsilon to compute the polarizability matrix and\nwrite it to file chimat. Use keyword skip_chi to read the polarizability\nmatrix from file chimat, construct the dielectric matrix, invert it and\nwrite the result to file epsmat.", [], [], ""],
    "spherical_truncation": ["keyword", "toggle", "", false, "", "Truncate the Coulomb potential based on an analytical scheme.\nThis is ok for quasi-spherical systems, such as CH4 molecule or C60,\nbut the `cell_box_truncation` is the most general and recommended\nscheme. When using spherical truncation, you must also specify the\nradius for the truncation in `spherical_truncation`.", [], [], ""],
    "stop_after_qpt": ["keyword", "integer", "", false, "", "Allows to stop the epsilon calculation after the specified number of q-points are\ncalculated (default -1, meaning all q-points calculated).", [], [], "2"],
    "sub_collective_eigen_redistr": ["keyword", "toggle", "", false, "", "Replicate eigenvectors using collective operation in the basis transformation step,\nperforms in general worse than point to point, mainly used for debugging.", [], [], ""],
    "subsample": ["keyword", "toggle", "", false, "", "Use this option to generate an eps0mat file suitable for subsampled Sigma\ncalculations. The only thing this flag does is to allow a calculation with\nmore than one $q\\rightarrow0$ points without complaining.", [], [], ""],
    "subspace_dont_keep_full_eps_omega0": ["keyword", "toggle", "", false, "", "Discharge the output of the full static epsilon matrix in the `eps0mat[.h5]` and\n`epsmat[.h5]` files.", [], [], ""],
    "subspace_use_elpa": ["keyword", "toggle", "", false, "", "If ELPA library is linked, specify to use ELPA for the diagonalization of the static\npolarizability.", [], [], ""],
    "use_wfn_hdf5": ["keyword", "toggle", "", false, "", "Read input wavefunction files in HDF5 format: `WFN.h5` instead of `WFN` and,\nif required, `WFNq.h5` instead of `WFNq`.", [], [], ""],
    "verbosity": ["keyword", "integer", "", false, "", "Verbosity level, options are:\n\n- 1: default\n- 2: medium - info about k-points, symmetries, and eqp corrections.\n- 3: high   - full dump of the reduced and unfolded k-points.\n- 4: log    - log of various function calls. Use to debug code.\n- 5: debug  - extra debug statements. Use to debug code.\n- 6: max    - only use if instructed to, severe performance downgrade.\nNote that verbosity levels are cumulative. Most users will want to stick\nwith level 1 and, at most, level 3. Only use level 4+ if debugging the code.", [["1","default"],["2","medium - info about k-points, symmetries, and eqp corrections."],["3","high - full dump of the reduced and unfolded k-points."],["4","log - log of various function calls. Use to debug code."],["5","debug - extra debug statements. Use to debug code."],["6","max - only use if instructed to, severe performance downgrade."]], [], "1"],
